// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { submitPetForm } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:4200");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(65000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/pets/1/edit`);
    await page.locator("#nickname").fill("Leonardo");
    await expect(page.getByRole("textbox", { name: "Name", exact: true })).toHaveValue("Leo");
    const updateResponse = await submitPetForm(page, "Update Pet", "**/petclinic/api/pets/**");
    expect(updateResponse.status()).toBe(204);

    // Saving redirects back to the owner detail page.
    await expect(page).toHaveURL(/\/petclinic\/owners\/1$/);

    // The edited nickname must have persisted to the API.
    const petResponse = await page.request.get(`${baseUrl}/petclinic/api/pets/1`);
    expect(petResponse.status()).toBe(200);
    const pet = await petResponse.json();
    expect(pet.id).toBe(1);
    expect(pet.name).toBe("Leo");
    expect(pet.nickname).toBe("Leonardo");
    expect(pet.birthDate).toBe("2010-09-07");

    // ...and the pet list on the owner detail page must surface it.
    await expect(page.locator("main")).toContainText("Leonardo");
});
